window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-02f1030613d493bb"]={"versions": [{"id": "FIG-02f1030613d493bb", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodikdiagramm der AUTOSAR-Methodik (AUTOSAR_TR_Methodology). Das Diagramm spezifiziert die Aktivität „Configure Mode Management“ innerhalb des BSW- und ECU-Integrationsprozesses auf Steuergeräteebene sowie deren Interaktion mit Artefakten und Rollen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rolle:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> (Multiplizität 1): Ausführende Ingenieursrolle, verbunden über die Stereotyp-Beziehung <code>«performs»</code>.\n</li></ul>\n</li><li>Aktivität:\n<ul class=\"fig-list\"><li><code>Configure Mode Management</code>: Zentraler Prozessschritt zur Konfiguration des Betriebsmodi-Managements (BswM, EcuM etc.).\n</li></ul>\n</li><li>Eingangsartefakte (<code>«input»</code>):\n<ul class=\"fig-list\"><li><code>BSW Module Delivered Bundle</code> (Multiplizität 0..1): Liefert die BSW-Modulbeschreibungen und Basissoftware-Pakete.\n</li><li><code>ECU Extract</code> (Multiplizität 1): Auszug der Systemkonfiguration für das spezifische Steuergerät mit Kommunikations- und Modus-Anforderungen.\n</li><li><code>AUTOSAR Standardized ECU Configuration Description</code> (im Diagramm angeschnitten beschriftet als <code>AUTOSAR Standardized ECU</code>, Multiplizität 0..1): Standardisierte Parameterdefinitionen und Vorkonfigurationen.\n</li></ul>\n</li><li>Ein-/Ausgangsartefakt (<code>«inoutput»</code>):\n<ul class=\"fig-list\"><li><code>ECU Configuration Values</code> (Multiplizität 1): Bestehende Steuergeräte-Konfigurationswerte, die durch die Aktivität gelesen und um die modusspezifischen Konfigurationsparameter aktualisiert bzw. erweitert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> initiiert und steuert die Aktivität <code>Configure Mode Management</code>.\n</li><li>Als verbindliche Eingangsbasis dient der <code>ECU Extract</code> (Multiplizität 1), optional ergänzt durch das <code>BSW Module Delivered Bundle</code> (0..1) sowie standardisierte ECU-Konfigurationsbeschreibungen (<code>AUTOSAR Standardized ECU...</code>, 0..1).\n</li><li>Bereits vorhandene Konfigurationswerte (<code>ECU Configuration Values</code>, 1) werden eingelesen (<code>«inoutput»</code>).\n</li><li>Auf Basis der Modusmanagement-Anforderungen werden die BSW-Modi, Zustandstransitionen, Rules, Actions und Schnittstellen konfiguriert und in die <code>ECU Configuration Values</code> (1) zurückgeschrieben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der <code>ECU Extract</code> ist als Pflichteingabe (Multiplizität 1) zwingend erforderlich, da er die signalspezifischen und funktionalen Modusanforderungen der Systemebene an das Steuergerät enthält.\n</li><li><code>ECU Configuration Values</code> fungiert als <code>«inoutput»</code> mit Multiplizität 1; die Aktivität modifiziert somit eine existierende Konfiguration und erzeugt kein isoliertes neues Konfigurationsdokument.\n</li><li>Die Ausführung erfordert typischerweise spezialisierte AUTOSAR-Authoring-/BswM-Generierungswerkzeuge, um Konsistenz zwischen EcuM-, BswM- und RTE-Modus-Deklarationen sicherzustellen.\n</li></ul>"}, {"id": "FIG-35717d7f40dac0ec", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodikdiagramm der AUTOSAR-Methodik (AUTOSAR_TR_Methodology). Das Diagramm spezifiziert die Aktivität „Configure Mode Management“ innerhalb des BSW- und ECU-Integrationsprozesses auf Steuergeräteebene sowie deren Interaktion mit Artefakten und Rollen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rolle:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> (Multiplizität 1): Ausführende Ingenieursrolle, verbunden über die Stereotyp-Beziehung <code>«performs»</code>.\n</li></ul>\n</li><li>Aktivität:\n<ul class=\"fig-list\"><li><code>Configure Mode Management</code>: Zentraler Prozessschritt zur Konfiguration des Betriebsmodi-Managements (BswM, EcuM etc.).\n</li></ul>\n</li><li>Eingangsartefakte (<code>«input»</code>):\n<ul class=\"fig-list\"><li><code>BSW Module Delivered Bundle</code> (Multiplizität 0..1): Liefert die BSW-Modulbeschreibungen und Basissoftware-Pakete.\n</li><li><code>ECU Extract</code> (Multiplizität 1): Auszug der Systemkonfiguration für das spezifische Steuergerät mit Kommunikations- und Modus-Anforderungen.\n</li><li><code>AUTOSAR Standardized ECU Configuration Description</code> (im Diagramm angeschnitten beschriftet als <code>AUTOSAR Standardized ECU</code>, Multiplizität 0..1): Standardisierte Parameterdefinitionen und Vorkonfigurationen.\n</li></ul>\n</li><li>Ein-/Ausgangsartefakt (<code>«inoutput»</code>):\n<ul class=\"fig-list\"><li><code>ECU Configuration Values</code> (Multiplizität 1): Bestehende Steuergeräte-Konfigurationswerte, die durch die Aktivität gelesen und um die modusspezifischen Konfigurationsparameter aktualisiert bzw. erweitert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> initiiert und steuert die Aktivität <code>Configure Mode Management</code>.\n</li><li>Als verbindliche Eingangsbasis dient der <code>ECU Extract</code> (Multiplizität 1), optional ergänzt durch das <code>BSW Module Delivered Bundle</code> (0..1) sowie standardisierte ECU-Konfigurationsbeschreibungen (<code>AUTOSAR Standardized ECU...</code>, 0..1).\n</li><li>Bereits vorhandene Konfigurationswerte (<code>ECU Configuration Values</code>, 1) werden eingelesen (<code>«inoutput»</code>).\n</li><li>Auf Basis der Modusmanagement-Anforderungen werden die BSW-Modi, Zustandstransitionen, Rules, Actions und Schnittstellen konfiguriert und in die <code>ECU Configuration Values</code> (1) zurückgeschrieben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der <code>ECU Extract</code> ist als Pflichteingabe (Multiplizität 1) zwingend erforderlich, da er die signalspezifischen und funktionalen Modusanforderungen der Systemebene an das Steuergerät enthält.\n</li><li><code>ECU Configuration Values</code> fungiert als <code>«inoutput»</code> mit Multiplizität 1; die Aktivität modifiziert somit eine existierende Konfiguration und erzeugt kein isoliertes neues Konfigurationsdokument.\n</li><li>Die Ausführung erfordert typischerweise spezialisierte AUTOSAR-Authoring-/BswM-Generierungswerkzeuge, um Konsistenz zwischen EcuM-, BswM- und RTE-Modus-Deklarationen sicherzustellen.\n</li></ul>"}, {"id": "FIG-f0145b26e7147c0f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodikdiagramm der AUTOSAR-Methodik (AUTOSAR_TR_Methodology). Das Diagramm spezifiziert die Aktivität „Configure Mode Management“ innerhalb des BSW- und ECU-Integrationsprozesses auf Steuergeräteebene sowie deren Interaktion mit Artefakten und Rollen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rolle:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> (Multiplizität 1): Ausführende Ingenieursrolle, verbunden über die Stereotyp-Beziehung <code>«performs»</code>.\n</li></ul>\n</li><li>Aktivität:\n<ul class=\"fig-list\"><li><code>Configure Mode Management</code>: Zentraler Prozessschritt zur Konfiguration des Betriebsmodi-Managements (BswM, EcuM etc.).\n</li></ul>\n</li><li>Eingangsartefakte (<code>«input»</code>):\n<ul class=\"fig-list\"><li><code>BSW Module Delivered Bundle</code> (Multiplizität 0..1): Liefert die BSW-Modulbeschreibungen und Basissoftware-Pakete.\n</li><li><code>ECU Extract</code> (Multiplizität 1): Auszug der Systemkonfiguration für das spezifische Steuergerät mit Kommunikations- und Modus-Anforderungen.\n</li><li><code>AUTOSAR Standardized ECU Configuration Description</code> (im Diagramm angeschnitten beschriftet als <code>AUTOSAR Standardized ECU</code>, Multiplizität 0..1): Standardisierte Parameterdefinitionen und Vorkonfigurationen.\n</li></ul>\n</li><li>Ein-/Ausgangsartefakt (<code>«inoutput»</code>):\n<ul class=\"fig-list\"><li><code>ECU Configuration Values</code> (Multiplizität 1): Bestehende Steuergeräte-Konfigurationswerte, die durch die Aktivität gelesen und um die modusspezifischen Konfigurationsparameter aktualisiert bzw. erweitert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> initiiert und steuert die Aktivität <code>Configure Mode Management</code>.\n</li><li>Als verbindliche Eingangsbasis dient der <code>ECU Extract</code> (Multiplizität 1), optional ergänzt durch das <code>BSW Module Delivered Bundle</code> (0..1) sowie standardisierte ECU-Konfigurationsbeschreibungen (<code>AUTOSAR Standardized ECU...</code>, 0..1).\n</li><li>Bereits vorhandene Konfigurationswerte (<code>ECU Configuration Values</code>, 1) werden eingelesen (<code>«inoutput»</code>).\n</li><li>Auf Basis der Modusmanagement-Anforderungen werden die BSW-Modi, Zustandstransitionen, Rules, Actions und Schnittstellen konfiguriert und in die <code>ECU Configuration Values</code> (1) zurückgeschrieben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der <code>ECU Extract</code> ist als Pflichteingabe (Multiplizität 1) zwingend erforderlich, da er die signalspezifischen und funktionalen Modusanforderungen der Systemebene an das Steuergerät enthält.\n</li><li><code>ECU Configuration Values</code> fungiert als <code>«inoutput»</code> mit Multiplizität 1; die Aktivität modifiziert somit eine existierende Konfiguration und erzeugt kein isoliertes neues Konfigurationsdokument.\n</li><li>Die Ausführung erfordert typischerweise spezialisierte AUTOSAR-Authoring-/BswM-Generierungswerkzeuge, um Konsistenz zwischen EcuM-, BswM- und RTE-Modus-Deklarationen sicherzustellen.\n</li></ul>"}], "trans": [{"from": "FIG-02f1030613d493bb", "to": "FIG-35717d7f40dac0ec", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-35717d7f40dac0ec", "to": "FIG-f0145b26e7147c0f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
